const CatalogEntry* catalog(const char* code, std::size_t& count) {
    count = 0;
    if (std::strcmp(code, "ar") == 0) {
        count = 0;
        return k_ar;
    }
    if (std::strcmp(code, "cs") == 0) {
        count = 0;
        return k_cs;
    }
    if (std::strcmp(code, "es") == 0) {
        count = 3439;
        return k_es;
    }
    if (std::strcmp(code, "fr") == 0) {
        count = 3439;
        return k_fr;
    }
    if (std::strcmp(code, "hi") == 0) {
        count = 0;
        return k_hi;
    }
    if (std::strcmp(code, "id") == 0) {
        count = 0;
        return k_id;
    }
    if (std::strcmp(code, "it") == 0) {
        count = 0;
        return k_it;
    }
    if (std::strcmp(code, "ja") == 0) {
        count = 0;
        return k_ja;
    }
    if (std::strcmp(code, "ko") == 0) {
        count = 0;
        return k_ko;
    }
    if (std::strcmp(code, "nl") == 0) {
        count = 0;
        return k_nl;
    }
    if (std::strcmp(code, "pl") == 0) {
        count = 0;
        return k_pl;
    }
    if (std::strcmp(code, "pt") == 0) {
        count = 3439;
        return k_pt;
    }
    if (std::strcmp(code, "ru") == 0) {
        count = 3439;
        return k_ru;
    }
    if (std::strcmp(code, "tr") == 0) {
        count = 0;
        return k_tr;
    }
    if (std::strcmp(code, "uk") == 0) {
        count = 0;
        return k_uk;
    }
    if (std::strcmp(code, "zh") == 0) {
        count = 0;
        return k_zh;
    }
    return nullptr;
}

